changeSet.sql:
-- bng.projects carries the audit and updated_at triggers. This is a -- metadata-only normalisation, not a user project change, so suppress -- them exactly as changeSet 32 does: otherwise every affected project -- gains a false audit entry attributed to its owner and has its last -- genuine modification timestamp overwritten. PostgreSQL DDL is -- transactional, so a failed changeset restores the enabled state -- when Liquibase rolls the transaction back. ALTER TABLE bng.projects DISABLE TRIGGER write_audit_log; ALTER TABLE bng.projects DISABLE TRIGGER set_updated_at;
-- Drop the older half of any case-duplicate pair before folding case, -- or the UPDATE below would violate the unique constraints. ctid -- breaks ties so the delete is deterministic when two rows share a -- last_updated. DELETE FROM bng.roles a USING bng.roles b WHERE a.ctid <> b.ctid AND a.user_id = b.user_id AND a.name = b.name AND lower(a.relationship_id) = lower(b.relationship_id) AND (a.last_updated < b.last_updated OR (a.last_updated = b.last_updated AND a.ctid < b.ctid));
DELETE FROM bng.relationships a USING bng.relationships b WHERE a.ctid <> b.ctid AND a.user_id = b.user_id AND lower(a.relationship_id) = lower(b.relationship_id) AND (a.last_updated < b.last_updated OR (a.last_updated = b.last_updated AND a.ctid < b.ctid));
UPDATE bng.roles SET relationship_id = lower(relationship_id) WHERE relationship_id <> lower(relationship_id);
UPDATE bng.relationships SET relationship_id = lower(relationship_id) WHERE relationship_id <> lower(relationship_id);
UPDATE bng.users SET current_relationship_id = lower(current_relationship_id) WHERE current_relationship_id <> lower(current_relationship_id);
UPDATE bng.projects SET relationship_id = lower(relationship_id) WHERE relationship_id <> lower(relationship_id);
ALTER TABLE bng.projects ENABLE TRIGGER write_audit_log; ALTER TABLE bng.projects ENABLE TRIGGER set_updated_at;
-- The RBAC EXISTS join folds case on both sides, which makes the -- plain idx_roles_user_rel usable only via its leading user_id -- column. This functional index restores an index-only path for the -- folded comparison. CREATE INDEX IF NOT EXISTS idx_roles_user_rel_lower ON bng.roles (user_id, lower(relationship_id));
